import{_ as t,o as s,c as e,a5 as d}from"./chunks/framework.CslsFoWx.js";const g=JSON.parse('{"title":"Tenancy, auth & appareils","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/01-tenancy-auth.md","filePath":"generated/modules/01-tenancy-auth.md","lastUpdated":null}'),n={name:"modules/01-tenancy-auth.md"};function r(i,a,p,o,l,c){return s(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="tenancy-auth-appareils" tabindex="-1">Tenancy, auth &amp; appareils <a class="header-anchor" href="#tenancy-auth-appareils" aria-label="Permalink to &quot;Tenancy, auth &amp; appareils&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 0 · <a href="/VendoraSystem-docs/specs/01-tenancy-auth">spécification complète</a></span></p><p>Socle multi-tenant : comptes, magasins, rôles, appairage des appareils, JWT + refresh, login caissier par PIN hors ligne, PIN manager et RLS Postgres. L&#39;essentiel est fait et prouvé sur la vraie stack (équipe, invitations, cache d&#39;auth chiffré, identité Ed25519) ; restent la checklist d&#39;onboarding web, les modules par profil, l&#39;écran Appareils, le transfert de propriété et l&#39;écart Argon2id.</p><div class="kpis"><div><b>19</b><span>faites</span></div><div><b>5</b><span>partielles</span></div><div><b>1</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="tenant-magasins" tabindex="-1">Tenant &amp; magasins <a class="header-anchor" href="#tenant-magasins" aria-label="Permalink to &quot;Tenant &amp; magasins&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Inscription du commerçant</strong><br><span class="muted">Créer en une fois le tenant, le compte propriétaire et le premier magasin avec son profil.<br><i>Lot R8 : page « Créer mon espace » (/inscription, lien depuis la connexion) — commerce, e-mail, mot de passe confirmé, activité en cartes (épicerie, restaurant, habillement, services, générique), premier magasin, devise, fuseau ; durée de l&#39;essai lue au catalogue public ; e-mail déjà pris (409) et inscription fermée (403) dits en clair ; session ouverte aussitôt. Reste : checklist d&#39;onboarding après l&#39;inscription.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-01</td><td>0.x, R8</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r8a-journal-inscription">📷</a></td></tr><tr><td><strong>Profils et modules par magasin</strong><br><span class="muted">Le profil choisi active les modules par défaut, activables ensuite un par un.<br><i>Le profil est enregistré sur le magasin ; la notion de module activable par profil reste à faire (TRACKING lot 2.1). Prévu phase 0 par la spec.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-AUTH-02, RG-AUTH-03</td><td></td><td></td></tr><tr><td><strong>Gestion des magasins</strong><br><span class="muted">Lister, créer, modifier et archiver les magasins du tenant.<br><i>Lot R1 : création (dans la limite de la formule), modification (nom, profil, fuseau ; devise tant qu&#39;aucune vente), archivage soft-delete (refusé pour le dernier magasin actif ou avec des appareils actifs, plus d&#39;appairage) et remise en service — page Magasins du back-office (propriétaire et administrateurs).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-04</td><td>0.x, R1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-lots-front-existants">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-r1-magasins-appareils">📷</a></td></tr></tbody></table><h2 id="utilisateurs-roles" tabindex="-1">Utilisateurs &amp; rôles <a class="header-anchor" href="#utilisateurs-roles" aria-label="Permalink to &quot;Utilisateurs &amp; rôles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rôles et contrôle d&#39;accès</strong><br><span class="muted">Rôles OWNER → KITCHEN vérifiés côté serveur (MANAGER+, publications réservées à l&#39;OWNER, 403 / 404).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-05, RG-AUTH-08</td><td>0.x, 1.x, 2.15, 2.18</td><td></td></tr><tr><td><strong>Équipe et PIN de caisse</strong><br><span class="muted">Ajouter un membre avec son PIN (unique par magasin), le réinitialiser, désactiver un utilisateur (déconnecté des caisses).<br><i>Désactivation d&#39;un utilisateur déjà connecté vérifiée par tests, pas à l&#39;écran.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-09, RG-AUTH-10</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-login-pin-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-login-pin-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-login-pin-ios">📷</a></td></tr><tr><td><strong>Invitation par email</strong><br><span class="muted">Inviter un membre (un ou plusieurs magasins, rôle ≤ le sien), lien 72 h, renvoi, activation publique avec mot de passe et PIN.<br><i>Envoi par SMTP réel prêt (tout fournisseur, variables POS_MAIL_*, email de test dans la Console Vendora) ; boîte simulée en développement. Reste : relance automatique des invitations expirées.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-07</td><td>2.18, 2.24</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-invitation-email">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-equipe">📷</a></td></tr><tr><td><strong>Changement de rôle</strong><br><span class="muted">Changer le rôle d&#39;un membre ; les caisses mettent à jour leur cache d&#39;auth (approbateur ajouté ou retiré).<br><i>Couvert par les tests, pas de capture du changement de rôle.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-07, RG-AUTH-24</td><td>2.18</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-invitation-email">📷</a></td></tr><tr><td><strong>Transfert de propriété</strong><br><span class="muted">L&#39;OWNER transfère la propriété du tenant avec confirmation par mot de passe.<br><i>Lot R1 : page Équipe (propriétaire) — membre ayant accès au back-office, confirmation par mot de passe ; le nouveau propriétaire l&#39;est dans tous les magasins, l&#39;ancien devient administrateur ; caisses informées, opération tracée.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-06</td><td>R1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r1-magasins-appareils">📷</a></td></tr></tbody></table><h2 id="appareils" tabindex="-1">Appareils <a class="header-anchor" href="#appareils" aria-label="Permalink to &quot;Appareils&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Appairage par code court</strong><br><span class="muted">Appairer une caisse, un téléphone ou un KDS avec un code de 6 caractères (15 min, usage unique) ; jeton d&#39;appareil haché, stocké dans Keychain / Keystore.<br><i>Appairage d&#39;un iPhone / iPad physique (signature d&#39;équipe) à faire par l&#39;utilisateur.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-AUTH-11, RG-AUTH-12</td><td>0.x, 1.x, 2.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-appairage-ios">📷</a></td></tr><tr><td><strong>Rôles d&#39;appareil</strong><br><span class="muted">Chaque appareil a un rôle qui plafonne ses capacités (caisse, téléphone de salle, KDS sans login).<br><i>REGISTER, WAITER_TERMINAL et KDS livrés ; KIOSK : app kiosque en phase 4 (spec 09).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-AUTH-13</td><td>1.x, 2.5, 2.15</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-ecran-cuisine">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a></td></tr><tr><td><strong>Révocation d&#39;un appareil</strong><br><span class="muted">Révoquer un appareil : jeton refusé (401) et appareil refusé sur le réseau du magasin.<br><i>Révocation motivée (lot R1) ; lot R6 : faits d&#39;un appareil révoqué d&#39;avant sa révocation en quarantaine, arbitrée au back-office (accepter / refuser avec motif, audit), ceux d&#39;après rejetés. Refus LAN à valider sur appareils physiques.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-14</td><td>0.x, 2.28, R1, R6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-identite-appareil">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r6-synchro">📷</a></td></tr><tr><td><strong>Écran Appareils du back-office</strong><br><span class="muted">Générer un code avec compte à rebours, voir les appareils (rôle, version, dernier contact) et les révoquer.<br><i>Lot R1 : page Appareils du back-office — code d&#39;appairage avec le rôle (caisse, téléphone de salle, écran cuisine), dernier contact (à chaque requête de l&#39;appareil, à la minute près), plateforme et version, « En ligne », renommage ; appareils révoqués à part avec le motif.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-15</td><td>2.15, R1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r1-magasins-appareils">📷</a></td></tr><tr><td><strong>Identité Ed25519 par appareil</strong><br><span class="muted">Chaque appareil signe ses messages LAN avec sa clé ; annuaire des pairs (actifs / révoqués) tiré du serveur.<br><i>Lot R6 : lots push signés et vérifiés par le serveur (<code>event_log.signature</code>). Hub à 3 appareils à valider sur matériel (VALIDATION-MATERIEL).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-20</td><td>2.26, 2.28, R6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-restaurant">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-identite-appareil">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r6-synchro">📷</a></td></tr></tbody></table><h2 id="authentification" tabindex="-1">Authentification <a class="header-anchor" href="#authentification" aria-label="Permalink to &quot;Authentification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Connexion back-office</strong><br><span class="muted">Email + mot de passe → JWT 15 min et refresh opaque à rotation (famille révoquée si réutilisation).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-16, RG-AUTH-17</td><td>0.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-lots-front-existants">📷</a></td></tr><tr><td><strong>Mot de passe oublié</strong><br><span class="muted">Demander et exécuter la réinitialisation du mot de passe back-office.<br><i>Lot R1 : « Mot de passe oublié ? » à la connexion — réponse identique que le compte existe ou non, lien par email (24 h, usage unique, un nouveau lien annule le précédent), 3 demandes par heure au plus ; sessions ouvertes fermées après le changement.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td></td><td>R1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r1-magasins-appareils">📷</a></td></tr><tr><td><strong>Login caissier par PIN</strong><br><span class="muted">« Qui êtes-vous ? » + PIN, vérifié hors ligne, verrou 5 essais / 5 min, changement d&#39;utilisateur, panier conservé.<br><i>Déconnexion après inactivité, bandeaux 72 h / hors ligne et restauration au redémarrage vérifiés par tests, pas à l&#39;écran.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-AUTH-18, RG-AUTH-19, RG-AUTH-23</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-login-pin-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-login-pin-ios">📷</a></td></tr><tr><td><strong>Délai d&#39;inactivité par magasin</strong><br><span class="muted">L&#39;OWNER règle le délai (30 s → 4 h) ; les caisses l&#39;appliquent sans redémarrage.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-19</td><td>2.24</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-equipe">📷</a></td></tr><tr><td><strong>PIN manager</strong><br><span class="muted">Les actions sensibles exigent le PIN d&#39;un manager + motif, vérifié hors ligne, tracé avec les deux identités.<br><i>Remise au-delà du seuil (lot 3.2) et casse / perte (lot 3.8) sous PIN faites ; seuil de PIN des sorties d&#39;espèces non configurable par magasin ; annulation de ligne en caisse sous PIN non faite.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-20</td><td>1.x, 2.8, 2.20, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-web">📷</a></td></tr><tr><td><strong>Traçage des PIN faux</strong><br><span class="muted">Chaque PIN faux et chaque verrou remontent au serveur (audit, alerte PIN_LOCK au tableau de bord).<br><i>Seuil et durée du verrou (5 / 5 min) non configurables.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-18</td><td>2.24</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-equipe">📷</a></td></tr></tbody></table><h2 id="auth-hors-ligne" tabindex="-1">Auth hors ligne <a class="header-anchor" href="#auth-hors-ligne" aria-label="Permalink to &quot;Auth hors ligne&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Cache d&#39;auth hors ligne</strong><br><span class="muted">Les caisses gardent les PIN hachés des membres (événements + GET auth-cache), valables 72 h, puis mode dégradé managers seuls.<br><i>Un PIN défini avant V9 doit être redéfini (pas de hash offline à servir).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-AUTH-22, RG-AUTH-23, RG-AUTH-24</td><td>1.x, 2.24</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-equipe">📷</a></td></tr><tr><td><strong>Cache d&#39;auth chiffré au repos</strong><br><span class="muted">Hash chiffrés AES-256-GCM avec une clé non exportable (Keystore / Keychain), bases exclues des sauvegardes.<br><i>Sauvegarde / restauration à rejouer sur appareils physiques (VALIDATION-MATERIEL §8).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-AUTH-22</td><td>1.x, 2.27</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-cache-chiffre-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-cache-chiffre-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-dette-technique">📷</a></td></tr><tr><td><strong>Hash Argon2id des PIN</strong><br><span class="muted">PIN et mots de passe hachés en Argon2id, jamais en clair ni dans les logs.<br><i>Écart assumé : PBKDF2-HMAC-SHA256 pour le hash offline (pas d&#39;Argon2id multiplateforme en Kotlin pur) ; décision à trancher (réviser la spec ou lib native).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td>RG-AUTH-21, RG-AUTH-22</td><td>1.x</td><td></td></tr></tbody></table><h2 id="securite-audit" tabindex="-1">Sécurité &amp; audit <a class="header-anchor" href="#securite-audit" aria-label="Permalink to &quot;Sécurité &amp; audit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Isolation multi-tenant (RLS)</strong><br><span class="muted">RLS FORCE fail-closed, rôle applicatif sans BYPASSRLS, tenant positionné par transaction, 404 pour un autre tenant.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-AUTH-27, RG-AUTH-28, RG-AUTH-29</td><td>0.x</td><td></td></tr><tr><td><strong>Vérification des événements hors ligne</strong><br><span class="muted">À la sync, le serveur exige le jeton d&#39;appareil et revérifie les approbations ; anomalie signalée, jamais de rejet.<br><i>Lot R6 : faits d&#39;un utilisateur inconnu du magasin ou d&#39;un appareil révoqué en quarantaine, jamais supprimés, arbitrés par un responsable au back-office.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-26</td><td>0.x, 1.x, 2.23, R6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r6-synchro">📷</a></td></tr><tr><td><strong>Journal d&#39;audit des actions d&#39;administration</strong><br><span class="muted">Invitations, rôles, politiques, clé LAN, thème… tracés dans un journal append-only (qui, quoi, avant / après).<br><i>Lot R8 : page « Journal d&#39;audit » — toutes les entrées du commerce (back-office et projections des caisses), filtres type, élément, action, auteur, magasin, période gardés dans l&#39;URL, 100 par page (« Plus anciennes »), changements avant → après en clair (montants dans la devise), détail JSON, export CSV ; MANAGER et plus, isolé par commerce.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-AUTH-30</td><td>2.3, 2.18, 2.22, 2.24, 2.26, R8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-modificateurs-suite">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r8a-journal-inscription">📷</a></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Checklist d&#39;onboarding après l&#39;inscription (l&#39;écran d&#39;inscription avec choix du profil est fait, lot R8).</li><li>Modules activables par profil et par magasin.</li><li>Création, modification et archivage des magasins.</li><li>Écran Appareils (code d&#39;appairage, liste, dernier contact, révocation) et heartbeat.</li><li>Transfert de propriété et réinitialisation du mot de passe.</li><li>Fournisseur SMTP réel pour les invitations.</li><li>Trancher Argon2id vs PBKDF2 pour le hash offline des PIN.</li><li>Quarantaine des événements d&#39;un appareil révoqué ou suspect.</li><li>Signature Ed25519 des lots push vérifiée par le serveur.</li><li>Seuil de PIN manager par magasin et actions sensibles manquantes (remise, ajustement de stock).</li></ul>',18)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
